 create extension if not exists "pgcrypto";
create table if not exists admin_profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'editor' check (role in ('admin','editor')), created_at timestamptz not null default now());
create table if not exists projects (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, description text not null, image_url text, published boolean not null default false, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists photos (id uuid primary key default gen_random_uuid(), title text, alt_text text not null, storage_path text not null, public_url text not null, published boolean not null default false, created_at timestamptz not null default now());
create table if not exists stories (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, excerpt text not null, content text not null, cover_image_url text, category text not null default 'General', published boolean not null default false, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists testimonials (id uuid primary key default gen_random_uuid(), quote text not null, author_name text not null, role text, image_url text, published boolean not null default false, created_at timestamptz not null default now());
create table if not exists videos (id uuid primary key default gen_random_uuid(), title text not null, description text, youtube_url text not null, thumbnail_url text, published boolean not null default false, created_at timestamptz not null default now());
create table if not exists quotes (id uuid primary key default gen_random_uuid(), text text not null, attribution text, published boolean not null default false, created_at timestamptz not null default now());
create table if not exists site_settings (key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create or replace function set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists projects_updated_at on projects; create trigger projects_updated_at before update on projects for each row execute function set_updated_at();
drop trigger if exists stories_updated_at on stories; create trigger stories_updated_at before update on stories for each row execute function set_updated_at();
create or replace function is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from admin_profiles where id = auth.uid()); $$;
alter table admin_profiles enable row level security; alter table projects enable row level security; alter table photos enable row level security; alter table stories enable row level security; alter table testimonials enable row level security; alter table videos enable row level security; alter table quotes enable row level security; alter table site_settings enable row level security;
create policy "published projects are public" on projects for select using (published = true or is_admin());
create policy "published photos are public" on photos for select using (published = true or is_admin());
create policy "published stories are public" on stories for select using (published = true or is_admin());
create policy "published testimonials are public" on testimonials for select using (published = true or is_admin());
create policy "published videos are public" on videos for select using (published = true or is_admin());
create policy "published quotes are public" on quotes for select using (published = true or is_admin());
create policy "settings readable" on site_settings for select using (true);
create policy "admins read own profile" on admin_profiles for select using (id = auth.uid());
create policy "admins manage projects" on projects for all using (is_admin()) with check (is_admin());
create policy "admins manage photos" on photos for all using (is_admin()) with check (is_admin());
create policy "admins manage stories" on stories for all using (is_admin()) with check (is_admin());
create policy "admins manage testimonials" on testimonials for all using (is_admin()) with check (is_admin());
create policy "admins manage videos" on videos for all using (is_admin()) with check (is_admin());
create policy "admins manage quotes" on quotes for all using (is_admin()) with check (is_admin());
create policy "admins manage settings" on site_settings for all using (is_admin()) with check (is_admin());
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('project-media', 'project-media', true, 5242880, array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy "public media read" on storage.objects for select using (bucket_id = 'project-media');
create policy "admins upload media" on storage.objects for insert with check (bucket_id = 'project-media' and is_admin());
create policy "admins update media" on storage.objects for update using (bucket_id = 'project-media' and is_admin());
create policy "admins delete media" on storage.objects for delete using (bucket_id = 'project-media' and is_admin());
